public class Main {
    public static void main(String[] args) {
        Animal[] animals = {new Dog(), new Cat(), new Dog()};
        int dogs = 0;
        for (Animal a : animals) {
            if (a instanceof Dog) {
                Dog d = (Dog) a;
                d.fetch();
                dogs++;
            }
        }
        System.out.println("Dogs: " + dogs);
    }
}

class Animal {
}

class Dog extends Animal {
    void fetch() {
        System.out.println("Fetching!");
    }
}

class Cat extends Animal {
}
